# Encode demo boundary/interior sets and test marker arrangement for symmetric diagonal pairs.
demo1={(0,3),(1,2),(1,4),(2,1),(2,5),(3,0),(3,6)}
demo2={(0,1),(0,5),(1,2),(1,4),(2,3)}
test={(0,2),(0,8),(1,1),(1,3),(1,7),(2,0),(2,4),(2,6),(3,5)}
print('demo1 interior', sorted((r,c) for r,lo,hi in [(1,3,3),(2,2,4),(3,1,5)] for c in range(lo,hi+1) if (r,c) not in demo1))
print('demo2 interior', sorted((r,c) for r,lo,hi in [(0,2,4),(1,3,3)] for c in range(lo,hi+1) if (r,c) not in demo2))
print('test widening left apex fill proposal',[(1,2),(2,1),(2,2),(2,3),(3,0),(3,1),(3,2),(3,3),(3,4)])

# Check geometric rails in current grid by row, zero-based.
for r,row in enumerate([[0,0,6,0,0,0,0,0,6],[0,6,0,6,0,0,0,6,0],[6,0,0,0,6,0,6,0,0],[0,0,0,0,0,6,0,0,0]]):
 print(r,[c for c,x in enumerate(row) if x==6])

g=[[0,0,6,0,0,0,0,0,6],[0,6,0,6,0,0,0,6,0],[6,0,0,0,6,0,6,0,0],[0,0,0,0,0,6,0,0,0]]
# Interiors of the two evident diagonal V/triangle outlines:
# outward V centered at (0,2), clipped at the left edge at row 3;
# inverted V from top endpoints (0,2),(0,8) to apex (3,5).
for r,lo,hi in [(0,3,7),(1,2,2),(1,4,6),(2,1,3),(2,5,5),(3,0,4)]:
 for c in range(lo,hi+1):
  assert g[r][c]==0, (r,c,g[r][c])
  g[r][c]=2
assert len(g)==4 and all(len(row)==9 for row in g)
print(g)

demo1_markers={(0,3),(1,2),(1,4),(2,1),(2,5),(3,0),(3,6)}
demo2_markers={(0,1),(0,5),(1,2),(1,4),(2,3)}
print('D1 output additions: between paired diagonals at rows 1..3:', [[(r,c) for c in range(4-r+1,4+r) if (r,c) not in demo1_markers] for r in range(1,4)])
print('D2 output additions:', [[(r,c) for c in range(2+r,5-r) if (r,c) not in demo2_markers] for r in range(2)])

g=[[0,0,6,0,0,0,0,0,6],[0,6,0,6,0,0,0,6,0],[6,0,0,0,6,0,6,0,0],[0,0,0,0,0,6,0,0,0]]
out=[row[:] for row in g]
for row in out:
    marks=[i for i,v in enumerate(row) if v==6]
    if len(marks)>=2:
        for c in range(marks[0]+1,marks[-1]):
            if row[c]==0: row[c]=2
assert len(out)==4 and all(len(r)==9 for r in out)
assert all(out[r][c] in (0,2,6) for r in range(4) for c in range(9))
print(out)
